Ltac n1_m264_rb cs :=
  lazymatch cs with
  | C8 ?v :: CB 16 (skipn 8 (cells_bytes (sql_fr_x1_6 ?P ?c))) :: ?rest => constr:(CB 24 (cells_bytes (sql_fr_x1_6 P v)) :: rest)
  | ?c :: ?rest => let r := n1_m264_rb rest in constr:(c :: r)
  end.
Ltac n1_m264 H :=
  lazymatch type of H with rw_cells ?segs ?m ?A ?cs =>
    let cs' := n1_m264_rb cs in
    let H' := fresh in
    let WF := fresh "WF" in
    assert (H' : rw_cells segs m A cs')
      by (pose proof H as [[WF _] _]; eapply rw_cells_recell;
          [exact H | cbn [cells_wf cell_wf] in WF |- *; clear - WF; repeat split; first [exact (sql_fr_x1_6_len _ _) | tauto] | reflexivity]);
    clear H; rename H' into H
  end.

