      | |- ?UNEXPECTED => fail 99 "unexpected goal after the run:" UNEXPECTED
      end).
Qed.

Lemma n1_litloop_ok : forall P OEND LLO LEND LOCV K, sql_static P OEND LLO LEND LOCV -> 1 <= K <= l_nbSeq P ->
  n1_match P OEND LLO LEND LOCV K -> n1_litloop P OEND LLO LEND LOCV K.
Proof.
  intros P OEND LLO LEND LOCV K ST HK CONT1. unfold n1_litloop.
  intros m1 c8 c16 c376 cw bc ptr sLL sOF sML p0 p1 p2 rl rm ro LP OP llv mlv ofs ile sl ole cur src sn cidx dll dml dof x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x28 x29 x30 x31 INV LF HO FAST E1 E2 E3 HC ES HSN HS8 HCI HDL HDM HDO HRING.
  eapply (n1_litloop_aux (Z.to_nat (ole - cur)) P OEND LLO LEND LOCV K ST HK CONT1); try eassumption. lia.
Qed.

